@once
@push('styles')
<style>
.vl-panel{margin:24px 0;padding:clamp(18px,3vw,30px);border:1px solid #d5e3ee;border-radius:18px;background:#fff;color:#162c43;min-width:0}.vl-eyebrow{font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase;color:#087e8b}.vl-panel h2{margin:8px 0 12px;font-size:clamp(23px,3vw,32px)}.vl-panel h3{font-size:17px;margin:20px 0 10px}.vl-muted{color:#52677a;line-height:1.6}.vl-flow{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;padding:0;list-style:none;counter-reset:step}.vl-flow li{position:relative;padding:16px;border:1px solid #c6dfe4;border-radius:12px;background:#f0f9fa;counter-increment:step}.vl-flow li:before{content:counter(step,decimal-leading-zero);display:block;font-size:12px;font-weight:800;color:#087e8b;margin-bottom:8px}.vl-flow li:not(:last-child):after{content:'\2192';position:absolute;right:-14px;top:40%;color:#087e8b}.vl-flow strong,.vl-flow span{display:block}.vl-flow span{font-size:13px;line-height:1.6;margin-top:8px;color:#405b6a}.vl-table-wrap{max-width:100%;overflow-x:auto;border:1px solid #d9e5ee;border-radius:12px}.vl-table{width:100%;min-width:460px;border-collapse:collapse;text-align:left;font-size:14px}.vl-table caption{text-align:left;padding:12px 16px;font-weight:800;background:#f2f7fc}.vl-table th,.vl-table td{padding:12px 16px;border-bottom:1px solid #e1eaf1;vertical-align:top;line-height:1.6;overflow-wrap:anywhere}.vl-table thead{background:#eaf3f7}.vl-table tr:last-child td{border-bottom:0}.vl-points{margin:10px 0;padding-left:22px;line-height:1.8}.vl-points li+li{margin-top:7px}.vl-callout{padding:14px 17px;border-left:4px solid #de9b26;background:#fff8e8;border-radius:0 9px 9px 0;line-height:1.7;margin-top:18px}.vl-code{max-width:100%;overflow:auto;padding:18px;border-radius:10px;background:#112437;color:#d4f7e9;font:13px/1.7 Consolas,monospace;white-space:pre-wrap;overflow-wrap:anywhere}.vl-recall{margin-top:18px;border:1px solid #d1dfe9;border-radius:12px;padding:14px}.vl-recall>summary{display:list-item!important;list-style:disclosure-closed!important;padding:0!important;cursor:pointer;font-size:15px;font-weight:750}.vl-recall[open]>summary{list-style:disclosure-open!important}.vl-notes{display:block;margin:12px 0}.vl-notes textarea{box-sizing:border-box;display:block;width:100%;min-height:90px;padding:12px;font:inherit;line-height:1.5;border:1px solid #bbcddb;border-radius:8px;resize:vertical}.vl-source{display:inline-block;margin-top:12px;font-size:12px;color:#08677b}.vl-mode{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:18px 0;padding:12px 16px;border-radius:10px;background:#edf4ff}.vl-mode input{accent-color:#087e8b}.vl-answer[hidden],[data-vl-reveal][hidden]{display:none!important}.vl-practice-label{display:block;font-size:12px;color:#7b5b12;font-weight:750}.vl-note-status{font-size:12px;color:#52677a}.vl-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}.vl-grid>*{min-width:0}@media(max-width:800px){.vl-flow{grid-template-columns:1fr 1fr}.vl-flow li:nth-child(2):after{display:none}.vl-grid{grid-template-columns:1fr}}@media(max-width:450px){.vl-flow{grid-template-columns:1fr}.vl-flow li:not(:last-child):after{content:'\2193';right:50%;top:auto;bottom:-19px}.vl-flow li:nth-child(2):after{display:block}.vl-table th,.vl-table td{padding:10px}.vl-panel{padding:16px}}
</style>
@endpush
@push('scripts')
<script>
(()=>{
 const key=name=>'ascendia:learning:'+location.pathname+':'+name;
 document.querySelectorAll('[data-vl-notes]').forEach(field=>{const status=field.parentElement.querySelector('.vl-note-status');try{field.value=localStorage.getItem(key(field.dataset.vlNotes))||'';}catch{status.textContent='Notes are available for this visit.';}field.addEventListener('input',()=>{try{localStorage.setItem(key(field.dataset.vlNotes),field.value);status.textContent='Saved on this browser.';}catch{status.textContent='Not saved; browser storage is unavailable.';}});});
 const toggle=document.querySelector('[data-vl-recall-mode]');
 toggle?.addEventListener('change',()=>{document.querySelectorAll('.vl-answer').forEach(answer=>answer.hidden=toggle.checked);document.querySelectorAll('[data-vl-reveal]').forEach(button=>button.hidden=!toggle.checked);});
 document.querySelectorAll('[data-vl-reveal]').forEach(button=>button.addEventListener('click',()=>{const answer=document.getElementById(button.dataset.vlReveal);answer.hidden=false;button.hidden=true;}));
})();
</script>
@endpush
@endonce
